/** Machine-readable failure reason. signed_out: the call needs the desk's endue ID and the desk is not signed in (or its sign-in ran out). offline: a service the call needs could not be reached, or did not answer in time. forbidden: that service refused the person (another person's agent, a plan that does not allow it); permission_denied is the desk's own refusal. */
export type ErrorCode =
  | "permission_denied"
  | "invalid_params"
  | "not_found"
  | "already_exists"
  | "io_error"
  | "timeout"
  | "cancelled"
  | "unsupported"
  | "invalid_value"
  | "internal"
  | "signed_out"
  | "offline"
  | "forbidden";

