/** How much an entry matters. */
export type LogLevel = "debug" | "info" | "warn" | "error";

/** One log entry. channel is the caller that wrote it, core for desk-core, or perm for the permission log the core keeps: every grant, every refusal and every call of an agent, with fields caller, permission, scope, decision (granted, allowed, approved, refused or denied), and target, reason, duration and grantId where they apply (ADR 0072). An approved irreversible call of an agent (approved) carries approval (once or task), approvalId and task where there is one; a call the person denied is refused with reason not-approved (ADR 0078). */
export interface LogEntry {
  /** RFC 3339 timestamp, set by the core. */
  at: string;
  channel: CallerId;
  level: LogLevel;
  message: string;
  /** Structured detail, any JSON object. */
  fields?: Record<string, unknown>;
}

/** Write an entry to the caller's own channel. */
export interface LogWriteRequest {
  id: RequestId;
  method: "log.write";
  params: LogWriteParams;
}

/** Parameters of log.write. */
export interface LogWriteParams {
  level: LogLevel;
  message: string;
  /** Structured detail, any JSON object. */
  fields?: Record<string, unknown>;
}

/** Result of log.write. */
export type LogWriteResult = Record<string, never>;

/** Read the latest entries of one channel, or of every channel. */
export interface LogTailRequest {
  id: RequestId;
  method: "log.tail";
  params: LogTailParams;
}

/** Parameters of log.tail. Without channel, every channel merged in time order; count defaults to 100. */
export interface LogTailParams {
  channel?: CallerId;
  count?: number;
  scope: LogReadPermission;
}

/** Result of log.tail, oldest entry first. */
export interface LogTailResult {
  entries: LogEntry[];
}

/** A new log entry. Sent to callers subscribed to log.entry that hold log:read. */
export interface LogEntryEvent {
  event: "log.entry";
  data: LogEntry;
}

/** List what the markets offer, every kind (ADR 0107). */
