/** A key in its owner's namespace, lowercase and dotted: voice, motion.reduce. */
export type SettingKey = string;

/** One setting with its owner. */
export interface Setting {
  owner: CallerId;
  key: SettingKey;
  /** Any JSON value. */
  value: unknown;
  migratedFrom?: MigratedFrom;
}

/** The earlier full name (owner.key, from the setting's renamed list) the value in force was read under, because no layer held one under the setting's own name. */
export type MigratedFrom = SettingName;

/** Read one setting: the caller's own, or another caller's under settings:read. */
export interface SettingsGetRequest {
  id: RequestId;
  method: "settings.get";
  params: SettingsGetParams;
}

/** Parameters of settings.get. owner defaults to the caller; another owner needs a scope that covers owner/key. */
export interface SettingsGetParams {
  key: SettingKey;
  owner?: CallerId;
  scope?: SettingsReadPermission;
}

/** Result of settings.get. value is absent when the key was never set. */
export interface SettingsGetResult {
  /** Any JSON value. */
  value?: unknown;
  migratedFrom?: MigratedFrom;
}

/** Write one of the caller's own settings (64 KiB of JSON at most). A value that fails the setting's declaration (kind, choices, minimum, maximum, pattern) is refused with invalid_value. */
export interface SettingsSetRequest {
  id: RequestId;
  method: "settings.set";
  params: SettingsSetParams;
}

/** Parameters of settings.set. */
export interface SettingsSetParams {
  key: SettingKey;
  /** Any JSON value. */
  value: unknown;
}

/** Result of settings.set. */
export type SettingsSetResult = Record<string, never>;

/** List settings: the caller's own, or every setting a settings:read scope covers. */
export interface SettingsListRequest {
  id: RequestId;
  method: "settings.list";
  params: SettingsListParams;
}

/** Parameters of settings.list. Without scope, the caller's own settings; with one, every setting it covers, whoever owns it. */
export interface SettingsListParams {
  scope?: SettingsReadPermission;
}

/** Result of settings.list, by owner and then key. */
export interface SettingsListResult {
  settings: Setting[];
}

/** A value a layer holds for a setting that fails its declaration, so the layer below is in force instead (for init.yaml, the default). file and line say where the value is written: init.yaml, a profile file or a plugin.json; a value set through settings.set has neither. */
export interface InvalidSetting {
  owner: CallerId;
  key: SettingKey;
  /** The value that failed. Any JSON value. */
  value: unknown;
  /** What it fails, for people: "purple" is not one of system, light, dark. */
  reason: string;
  file?: Path;
  /** The line of the setting's name in file, from 1. */
  line?: number;
}

/** A setting's value fell back. Sent to the setting's owner and to desk (the runtime, which tells the person) when the core first meets the value, and to desk again for every one still in force each time desk calls init.get. */
export interface SettingsInvalidEvent {
  event: "settings.invalid";
  data: InvalidSetting;
}

/** A setting changed. Sent to its owner, and to callers subscribed to settings.changed whose settings:read grant covers it. */
export interface SettingsChangedEvent {
  event: "settings.changed";
  data: Setting;
}

/** Open a URL in the system's default handler, or show a file in the file manager. */
export interface ShellOpenRequest {
  id: RequestId;
  method: "shell.open";
  params: ShellOpenParams;
}

/** Parameters of shell.open. */
export interface ShellOpenParams {
  /** An absolute URL (only http, https and mailto are ever opened), or with reveal a path (~/... or absolute) to show in its folder. */
  target: string;
  /** Show the file or folder at the path target, selected in its folder in the file manager, instead of opening a URL. A path is never opened or run. */
  reveal?: boolean;
  scope: ShellOpenPermission;
}

/** Result of shell.open: the system took the URL or showed the file. */
export interface ShellOpenResult {
  opened: true;
}

/** A key in the caller's own namespace. */
export type StoreKey = string;

/** Read one of the caller's values. */
export interface StoreGetRequest {
  id: RequestId;
  method: "store.get";
  params: StoreGetParams;
}

/** Parameters of store.get. */
export interface StoreGetParams {
  key: StoreKey;
}

/** Result of store.get. value is absent when the key was never set. */
export interface StoreGetResult {
  /** Any JSON value. */
  value?: unknown;
}

/** Write one of the caller's values (64 KiB of JSON at most). */
export interface StoreSetRequest {
  id: RequestId;
  method: "store.set";
  params: StoreSetParams;
}

/** Parameters of store.set. */
export interface StoreSetParams {
  key: StoreKey;
  /** Any JSON value. */
  value: unknown;
}

/** Result of store.set. */
export type StoreSetResult = Record<string, never>;

/** A space's id on endue AI. */
export type StudioSpaceId = string;

/** active, or archived: put away by the person and kept as it is. */
export type StudioSpaceStatus = "active" | "archived";

/** A space's newest result: its title and when it last changed. */
export interface StudioSpaceLatestResult {
  id: string;
  title: string;
  updatedAt: string;
}

/** How much is open in a space the person owns: work going on, items waiting for the person, its newest result and when it was last active. endue AI summarises only the spaces the person owns. */
export interface StudioSpaceSummary {
  activeWorkItems: number;
  openAttentionItems: number;
  latestResult?: StudioSpaceLatestResult;
  lastActivityAt?: string;
}

/** One space as endue AI lists it: its key, name, description and goal, its front agent (the one that answers the person), how it looks (avatarColor as #rrggbb, avatarGlyph of a character or two, an emoji perhaps; absent when none was set: draw one from the name) and its summary when endue AI gave one. The core passes only a colour of the form #rrggbb. Its picture is not carried: the desk loads no remote images. */
export interface StudioSpace {
  id: StudioSpaceId;
  key: string;
  name: string;
  description?: string;
  goal?: string;
  status: StudioSpaceStatus;
  frontAgentId?: StudioAgentId;
  avatarColor?: string;
  avatarGlyph?: string;
  summary?: StudioSpaceSummary;
  createdAt: string;
  updatedAt: string;
}

/** Every space the person can open, the most recently active first: the active ones, or the archived ones when asked. */
export interface StudioSpacesListRequest {
  id: RequestId;
  method: "studio.spaces.list";
  params: StudioSpacesListParams;
}

/** Parameters of studio.spaces.list: archived lists the archived spaces instead of the active ones. */
export interface StudioSpacesListParams {
  archived?: boolean;
  scope: StudioManagePermission;
}

/** Result of studio.spaces.list. */
export interface StudioSpacesListResult {
  spaces: StudioSpace[];
}

/** Work going on, items waiting for the person and results, in the whole space. */
export interface StudioSpaceCounts {
  activeWorkItems: number;
  openAttentionItems: number;
  results: number;
}

/** An agent taking part in the space: its role there (generalist, writer, or the person's own), whether it is the front agent, and whether it may run the space (admin) or only take part (participant). An agent of someone else's may take part: its name is not carried, so the desk names it from the person's own agents when it can. */
export interface StudioSpaceAgent {
  agentId: StudioAgentId;
  roleKey: string;
  front: boolean;
  permission: StudioSpaceAgentPermission;
}

/** What an agent may do in a space: run it (admin) or only take part (participant). */
export type StudioSpaceAgentPermission = "admin" | "participant";

/** How a piece of work stands, as endue.ai's space page words it. */
export type StudioSpaceWorkStatus =
  | "queued"
  | "preparing"
  | "in_progress"
  | "needs_you"
  | "stopping"
  | "pausing"
  | "paused"
  | "done"
  | "partly_done"
  | "failed"
  | "stopped";

/** A piece of work going on in the space. */
export interface StudioSpaceWork {
  id: string;
  title: string;
  status: StudioSpaceWorkStatus;
  updatedAt: string;
}

/** One of the space's newest results: its title, its kind (document, table, page) and when it last changed. */
export interface StudioSpaceResult {
  id: string;
  title: string;
  kind?: string;
  updatedAt: string;
}

/** A room's threads: with a discussion going on, waiting for the person, and unread. */
export interface StudioSpaceRoomThreads {
  active: number;
  needsYou: number;
  unread: number;
}

/** A room of the space, where its agents discuss: its name and topic, the messages the person has not read, when the last came, whether a discussion is going on, and its threads. Who is in the room is not carried. */
export interface StudioSpaceRoom {
  id: string;
  name: string;
  topic?: string;
  unreadCount: number;
  lastMessageAt?: string;
  discussing: boolean;
  threads?: StudioSpaceRoomThreads;
}

/** A part of what studio.spaces.get reads: the overview (counts, agents, work, results) or the rooms. */
export type StudioSpacePart = "overview" | "rooms";

/** A part endue AI did not answer for: the bridge error code it would have been, and a sentence for people. */
export interface StudioSpaceProblem {
  part: StudioSpacePart;
  code: ErrorCode;
  message: string;
}

/** What one space is doing, read at once: the space, its overview and its rooms that are not archived. The space itself must answer; a part that does not is left out and named in problems. */
export interface StudioSpacesGetRequest {
  id: RequestId;
  method: "studio.spaces.get";
  params: StudioSpaceParams;
}

/** Parameters of studio.spaces.get. */
export interface StudioSpaceParams {
  spaceId: StudioSpaceId;
  scope: StudioManagePermission;
}

/** Result of studio.spaces.get: the space, its counts (absent when the overview is in problems), the agents taking part (the front agent first), the work going on and the newest results (at most 5 each), and its rooms. A part in problems is absent (counts) or empty (the lists). */
export interface StudioSpacesGetResult {
  space: StudioSpace;
  counts?: StudioSpaceCounts;
  agents: StudioSpaceAgent[];
  work: StudioSpaceWork[];
  results: StudioSpaceResult[];
  rooms: StudioSpaceRoom[];
  problems: StudioSpaceProblem[];
}

/** An agent's id on endue AI (ag_ followed by a ULID today). */
export type StudioAgentId = string;

/** A published catalog agent's slug. */
export type StudioCatalogSlug = string;

/** The language catalog text and recommendations are asked in: ko or en, optionally with a region. */
export type StudioLocale = string;

/** A language the agent answers in, as an IETF BCP 47 tag (ko, en, ja, zh, en-US). */
export type StudioLanguage = string;

/** active: it works. inactive: turned off by the person (Disable), kept as it is. archived: put away by endue AI. deleted: soft-deleted, purged after 30 days; studio.agents.list leaves these out. */
export type StudioAgentStatus = "active" | "inactive" | "archived" | "deleted";

/** What studio.agents.setStatus can set: active (Enable) or inactive (Disable). */
export type StudioSwitch = "active" | "inactive";

/** Who can find the agent: public, unlisted (by link only) or private. */
export type StudioVisibility = "public" | "unlisted" | "private";

/** The catalog agent and version an agent was started from; it never changes. */
export interface StudioSourceCatalog {
  catalogAgentId: string;
  version: number;
}

/** One of the person's agents as endue AI lists it. slug is the handle endue AI derived from the first name; it never changes. avatarUrl is absent when none was set: draw one from the slug. The list carries no description; studio.agents.facets has it. */
export interface StudioAgent {
  id: StudioAgentId;
  slug: string;
  name: string;
  status: StudioAgentStatus;
  avatarUrl?: string;
  personalColor?: string;
  /** ISO 3166-2, where it was created (KR-11). */
  region?: string;
  sourceCatalog?: StudioSourceCatalog;
  createdAt: string;
  updatedAt: string;
}

/** The agent's personality coordinates, each from 0 to 1. A new agent without one gets endue.ai's defaults (tone 0.7, agency 0.3, thinking 0.2, rigor 0.85, expression 0.7, humor 0.15, integrity 0.85, epistemicHumility 0.65). */
export interface StudioPersonality {
  tone: number;
  agency: number;
  thinking: number;
  rigor: number;
  expression: number;
  humor: number;
  integrity: number;
  epistemicHumility: number;
}

/** A step of creating an agent that did not go through while the agent was made: its prompt, traits, skills or model; code is endue AI's, target the trait or skill it was about. */
export interface StudioWarning {
  step: StudioWarningStep;
  code: string;
  target?: string;
}

/** Which step a warning is about. */
export type StudioWarningStep = "prompt" | "traits" | "skills" | "model";

/** Parameters of studio.agents.list: the scope alone. */
export interface StudioParams {
  scope: StudioManagePermission;
}

/** Parameters of a call about one agent: studio.agents.get, studio.agents.remove and studio.agents.facets. */
export interface StudioAgentParams {
  agentId: StudioAgentId;
  scope: StudioManagePermission;
}

/** Every agent of the person's that is not deleted, the newest first: the core pages through endue AI's list (200 a page). */
export interface StudioAgentsListRequest {
  id: RequestId;
  method: "studio.agents.list";
  params: StudioParams;
}

/** Result of studio.agents.list. No agents is an empty list. */
export interface StudioAgentsListResult {
  agents: StudioAgent[];
}

/** One agent by id. Another person's agent is forbidden; one that is not there is not_found. */
export interface StudioAgentsGetRequest {
  id: RequestId;
  method: "studio.agents.get";
  params: StudioAgentParams;
}

/** Result of studio.agents.get. */
export interface StudioAgentsGetResult {
  agent: StudioAgent;
}

/** Build an agent from scratch, as endue.ai's Create does: a name and a role, in the languages given. A model, when given, is set as its chat model after it is made; when that fails the agent stays and a warning says so. */
export interface StudioAgentsCreateRequest {
  id: RequestId;
  method: "studio.agents.create";
  params: StudioAgentsCreateParams;
}

/** Parameters of studio.agents.create. name is what people call it (it gives the slug), role the work it does by default. languages is en unless given. */
export interface StudioAgentsCreateParams {
  name: string;
  role: string;
  description?: string;
  languages?: StudioLanguage[];
  personality?: StudioPersonality;
  model?: string;
  scope: StudioManagePermission;
}

/** Result of studio.agents.create: the new agent, and what did not go through. */
export interface StudioAgentsCreateResult {
  agent: StudioAgent;
  warnings: StudioWarning[];
}

/** Change an agent's identity (name, description, role, languages, personality, color) and settings (chat model, visibility). Only the fields given change; at least one is given. The slug never changes. */
export interface StudioAgentsUpdateRequest {
  id: RequestId;
  method: "studio.agents.update";
  params: StudioAgentsUpdateParams;
}

/** Parameters of studio.agents.update. model is the chat model's id; an empty string clears it, so endue AI's default applies. */
export interface StudioAgentsUpdateParams {
  agentId: StudioAgentId;
  name?: string;
  description?: string;
  role?: string;
  languages?: StudioLanguage[];
  personality?: StudioPersonality;
  personalColor?: string;
  model?: string;
  visibility?: StudioVisibility;
  scope: StudioManagePermission;
}

/** Result of studio.agents.update: the agent as endue AI has it now. */
export interface StudioAgentsUpdateResult {
  agent: StudioAgent;
}

/** Turn an agent off (inactive) or on again (active). Setting the status it already has is no error. */
export interface StudioAgentsSetStatusRequest {
  id: RequestId;
  method: "studio.agents.setStatus";
  params: StudioAgentsSetStatusParams;
}

/** Parameters of studio.agents.setStatus. */
export interface StudioAgentsSetStatusParams {
  agentId: StudioAgentId;
  status: StudioSwitch;
  scope: StudioManagePermission;
}

/** Result of studio.agents.setStatus: the agent with its new status. */
export interface StudioAgentsSetStatusResult {
  agent: StudioAgent;
}

/** Delete an agent. endue AI deletes softly: the agent leaves every list at once and is purged after 30 days. One already deleted is not_found. */
export interface StudioAgentsRemoveRequest {
  id: RequestId;
  method: "studio.agents.remove";
  params: StudioAgentParams;
}

/** Result of studio.agents.remove: the agent deleted. */
export interface StudioAgentsRemoveResult {
  agentId: StudioAgentId;
}

/** Who the agent is: its profile (name, description, avatar, color) and nature (role, languages, personality). */
export interface StudioIdentity {
  name: string;
  description?: string;
  avatarUrl?: string;
  personalColor?: string;
  /** The role it takes by default; empty when none is set. */
  role: string;
  languages: string[];
  personality?: StudioPersonality;
}

/** How endue AI picks a provider for the chat model: balanced, or throughput first. */
export type StudioRouting = "balanced" | "throughput";

/** The chat model: default (endue AI's own when absent), the fallback when the default fails, and the provider routing (balanced unless given). */
export interface StudioModel {
  default?: string;
  fallback?: string;
  routing?: StudioRouting;
}

/** The agent's settings Studio shows: who can find it, how long chats are kept (days), its chat model, the built-in tool groups it may not use and every group there is. */
export interface StudioSettings {
  visibility: StudioVisibility;
  chatHistoryRetention?: number;
  model: StudioModel;
  disabledToolGroups: string[];
  availableToolGroups?: string[];
  updatedAt?: string;
}

/** How a prompt revision was made: saved by hand (manual), carried over from older rules (migrated), or a restore of an earlier one (restore). */
export type StudioPromptSource = "manual" | "migrated" | "restore";

/** The agent's instructions, one Markdown document: the revision in force, its number and how it was made. */
export interface StudioPrompt {
  rev: number;
  content: string;
  source: StudioPromptSource;
  restoredFromRev?: number;
  createdAt: string;
}

/** One earlier or current revision of the prompt: its first 120 characters, and whether it is in force. */
export interface StudioPromptRevision {
  rev: number;
  source: StudioPromptSource;
  restoredFromRev?: number;
  preview: string;
  createdAt: string;
  active: boolean;
}

/** A skill bound to the agent: the binding's id, the skill, and whether it is on. */
export interface StudioSkill {
  id: string;
  skillId: string;
  slug?: string;
  name?: string;
  registrySkillId?: string;
  enabled: boolean;
}

/** A connection of the person's bound to the agent: the binding's id, whether it is on, and the connection's name, type and health as endue AI reports them. */
export interface StudioConnector {
  id: string;
  connectionId: string;
  enabled: boolean;
  name?: string;
  /** The connection type's name: slack, gmail, google_calendar. */
  type?: string;
  iconUrl?: string;
  status?: string;
}

/** A trait set on the agent (personality, self_evolving, ...): on or off, and when it changed. A trait never set is not listed. */
export interface StudioTrait {
  key: string;
  enabled: boolean;
  updatedAt?: string;
}

/** A part of what Studio shows of an agent. */
export type StudioFacet =
  | "identity"
  | "settings"
  | "prompt"
  | "revisions"
  | "skills"
  | "connectors"
  | "traits";

/** A facet endue AI did not answer for: the bridge error code it would have been, and a sentence for people. */
export interface StudioFacetProblem {
  facet: StudioFacet;
  code: ErrorCode;
  message: string;
}

/** Everything Studio shows of one agent, read at once: identity, settings, the prompt in force and its revisions (the newest 50), skills, connectors and traits. The agent itself must answer; a facet that does not is left out and named in problems. */
export interface StudioAgentsFacetsRequest {
  id: RequestId;
  method: "studio.agents.facets";
  params: StudioAgentParams;
}

/** Result of studio.agents.facets. prompt is absent when the agent has none yet; a facet in problems is absent (identity, settings) or empty (the lists). */
export interface StudioAgentsFacetsResult {
  agent: StudioAgent;
  identity?: StudioIdentity;
  settings?: StudioSettings;
  prompt?: StudioPrompt;
  revisions: StudioPromptRevision[];
  skills: StudioSkill[];
  connectors: StudioConnector[];
  traits: StudioTrait[];
  problems: StudioFacetProblem[];
}

/** Save the agent's instructions as a new revision in force (content), or put an earlier revision back in force as a new one (restore). */
export interface StudioAgentsPromptUpdateRequest {
  id: RequestId;
  method: "studio.agents.prompt.update";
  params: StudioAgentsPromptUpdateParams;
}

/** Parameters of studio.agents.prompt.update: content or restore, not both. */
export interface StudioAgentsPromptUpdateParams {
  agentId: StudioAgentId;
  content?: string;
  /** The revision to put back. */
  restore?: number;
  scope: StudioManagePermission;
}

/** Result of studio.agents.prompt.update: the revision now in force. */
export interface StudioAgentsPromptUpdateResult {
  prompt: StudioPrompt;
}

/** Catalog text in both languages endue AI writes it in. */
export interface StudioText {
  en: string;
  ko: string;
}

/** Something the catalog agent is good for, with an example request. */
export interface StudioUseCase {
  title: StudioText;
  example: StudioText;
}

/** A connection type a catalog agent works with (connection_type.name: slack, gmail), and whether it needs it. */
export interface StudioConnectorRef {
  type: string;
  required: boolean;
}

/** official: endue publishes it. user: a person does. */
export type StudioPublisherKind = "official" | "user";

/** Who published a catalog agent: endue (official) or a person (user). */
export interface StudioPublisher {
  kind: StudioPublisherKind;
  name: string;
}

/** What starting from a catalog agent sets up: traits, skills and the chat model. */
export interface StudioPreset {
  traits: string[];
  skills: string[];
  model?: string;
}

/** A published agent of endue AI's catalog, a template to start one's own agent from: its identity (name, role, avatar), tagline, description, strengths, use cases, the connectors and channels it works with, and its preset. Its instructions never leave endue AI. */
export interface StudioCatalogAgent {
  id: string;
  slug: StudioCatalogSlug;
  /** support, sales, marketing, research, engineering, operations, productivity, commerce, creative. */
  category: string;
  tags: string[];
  featured: boolean;
  publisher: StudioPublisher;
  version: number;
  name: string;
  role: StudioText;
  avatarUrl?: string;
  personalColor?: string;
  tagline: StudioText;
  description: StudioText;
  strengths: StudioText[];
  useCases: StudioUseCase[];
  connectors: StudioConnectorRef[];
  /** web, slack, kakao, navertalk, whatsapp, telegram. */
  channels: string[];
  preset: StudioPreset;
  publishedAt?: string;
}

/** The published catalog agents, featured first as endue AI orders them: those whose name, tagline or tags match query, in one category, at most limit (100 unless given). */
export interface StudioCatalogListRequest {
  id: RequestId;
  method: "studio.catalog.list";
  params: StudioCatalogListParams;
}

/** Parameters of studio.catalog.list. */
export interface StudioCatalogListParams {
  query?: string;
  category?: string;
  limit?: number;
  scope: StudioManagePermission;
}

/** Result of studio.catalog.list. */
export interface StudioCatalogListResult {
  agents: StudioCatalogAgent[];
}

/** Find catalog agents for what the person wants help with (Find an agent for me): endue AI answers the slugs that fit, best first, each with a reason, by its model or, when that is out, by keywords. */
export interface StudioCatalogRecommendRequest {
  id: RequestId;
  method: "studio.catalog.recommend";
  params: StudioCatalogRecommendParams;
}

/** Parameters of studio.catalog.recommend. locale is en unless given. */
export interface StudioCatalogRecommendParams {
  query: string;
  locale?: StudioLocale;
  scope: StudioManagePermission;
}

/** A catalog agent that fits, and why in one line (model output: show it as text only). */
export interface StudioRecommendation {
  slug: StudioCatalogSlug;
  reason: string;
}

/** Who chose the matches: endue AI's model (llm) or keyword overlap (keyword). */
export type StudioRecommendSource = "llm" | "keyword";

/** Result of studio.catalog.recommend. No match is an empty list. */
export interface StudioCatalogRecommendResult {
  matches: StudioRecommendation[];
  source: StudioRecommendSource;
}

/** Start an agent of the person's own from a catalog agent (Start with this agent): endue AI makes it with the catalog's identity, prompt, traits, skills and model, in locale. It may take up to 30 s. */
export interface StudioCatalogUseRequest {
  id: RequestId;
  method: "studio.catalog.use";
  params: StudioCatalogUseParams;
}

/** Parameters of studio.catalog.use. locale is en unless given. A slug the catalog does not publish is not_found. */
export interface StudioCatalogUseParams {
  slug: StudioCatalogSlug;
  locale?: StudioLocale;
  scope: StudioManagePermission;
}

/** What starting from the catalog set up: the prompt, the traits and skills named, and the model. */
export interface StudioApplied {
  prompt: boolean;
  traits: string[];
  skills: string[];
  model: boolean;
}

/** The catalog agent and version a new agent came from. */
export interface StudioCatalogRef {
  id: string;
  slug: StudioCatalogSlug;
  version: number;
}

/** What the person may connect next for the new agent: connectors and channels. */
export interface StudioRecommended {
  connectors: StudioConnectorRef[];
  channels: string[];
}

/** Result of studio.catalog.use: the new agent, the catalog agent it came from, what was set up, what was not (warnings), and what to connect next. */
export interface StudioCatalogUseResult {
  agent: StudioAgent;
  catalog: StudioCatalogRef;
  applied: StudioApplied;
  warnings: StudioWarning[];
  recommended: StudioRecommended;
}

/** active, archived or deleted, as endue AI keeps the conversation. */
export type StudioConversationStatus = "active" | "archived" | "deleted";

/** How the conversation's last run stands. */
export type StudioRunStatus = "running" | "completed" | "failed";

/** The Home board's column for a conversation, as endue.ai's Activity board sorts it: its last run is running (active), failed (failed), stopped waiting for the person (waiting), or anything else (done). */
export type StudioActivity = "waiting" | "active" | "failed" | "done";

/** One conversation with one of the person's agents: its title (absent when untitled), how many messages it has and when the last came, how its last run stands (the tool it runs now, or why it failed), whether it waits for the person, the start of the last answer (140 characters), and its column on the Home board. */
export interface StudioConversation {
  id: string;
  agentId: StudioAgentId;
  spaceId?: string;
  title?: string;
  status: StudioConversationStatus;
  messageCount: number;
  lastMessageAt?: string;
  lastReadAt?: string;
  pinnedAt?: string;
  lastRunStatus?: StudioRunStatus;
  awaitingInput?: boolean;
  lastMessagePreview?: string;
  currentTool?: string;
  lastRunErrorCode?: string;
  activity: StudioActivity;
  createdAt: string;
  updatedAt: string;
}

/** One page of the person's conversations, the most recently active first: one agent's when agentId is given, only those waiting for the person (awaitingInput) or with a run going on (running) when asked. */
export interface StudioConversationsListRequest {
  id: RequestId;
  method: "studio.conversations.list";
  params: StudioConversationsListParams;
}

/** Parameters of studio.conversations.list. page starts at 1; limit is 20 unless given. */
export interface StudioConversationsListParams {
  agentId?: StudioAgentId;
  awaitingInput?: boolean;
  running?: boolean;
  page?: number;
  limit?: number;
  scope: StudioManagePermission;
}

/** Result of studio.conversations.list: one page, how many match in all, and whether a page follows. */
export interface StudioConversationsListResult {
  conversations: StudioConversation[];
  total: number;
  hasMore: boolean;
}

/** One of the theme's font or image files, given inline. */
export interface ThemeSaveFile {
  path: ThemeAssetPath;
  base64: ThemeAssetData;
}

/** An https URL of a .desk-theme (or .desk-design) file. Plain http, and a redirect to another host, are refused. */
export type ThemeBundleUrl = string;

/** The sha256 of a file's bytes, lowercase hex. */
export type ThemeSha256 = string;

/** Save a theme as the person's own: write its folder in the user themes folder, check it as a theme plugin, then install it. It replaces an earlier user theme of the same id whole; when the check fails nothing is written and the earlier one stays. An id a built-in or any other plugin holds is already_exists. */
export interface ThemeSaveRequest {
  id: RequestId;
  method: "theme.save";
  params: ThemeSaveParams;
}

/** Parameters of theme.save. */
export interface ThemeSaveParams {
  /** The theme's plugin.json: kind theme, or kind design-system for a design system (ADR 0091), with an id inside local. (for example local.my-paper). */
  manifest: PluginManifest;
  /** Font and image files the theme block names, each path once. With the ones copyFrom brings they are the theme folder's only files besides plugin.json. */
  files?: ThemeSaveFile[];
  /** An installed theme (built-in, market or local) to copy files from: every font and backdrop image the saved theme block names that files does not give and that exists at the same path in that theme's folder. How a tuned copy keeps the fonts and images of the theme it started from. One that is not an installed theme is not_found. */
  copyFrom?: PluginId;
  scope: ThemeManagePermission;
}

/** Result of theme.save: the theme as installed. */
export interface ThemeSaveResult {
  plugin: PluginInfo;
}

/** Install a .desk-theme bundle as a user theme: given inline, read from a file, or downloaded over https and checked against its sha256 (a mismatch is invalid_params and nothing lands). A bundle whose id is outside local. and market. lands as local.<its name as a slug>. It is checked and replaces an earlier user theme of its id as theme.save does, except that a market. theme downloaded by url replaces an earlier one only while that one is still as its market published it (ADR 0060): one the person changed is already_exists and stays. */
export interface ThemeImportRequest {
  id: RequestId;
  method: "theme.import";
  params: ThemeImportParams;
}

/** Parameters of theme.import: exactly one of bundle, path and url, and sha256 with url (market only with url). */
export interface ThemeImportParams {
  bundle?: ThemeBundle;
  /** A .desk-theme or .desk-design file to read. */
  path?: Path;
  url?: ThemeBundleUrl;
  sha256?: ThemeSha256;
  /** With url, the market index that listed it: kept beside a market. theme with its version and sha256, so theme.market.list tells an update from the person's own changes. */
  market?: ThemeMarketUrl;
  scope: ThemeManagePermission;
}

/** Result of theme.import: the theme as installed, under the id it landed with. */
export interface ThemeImportResult {
  plugin: PluginInfo;
}

/** Make a .desk-theme bundle of any installed theme, built-in ones too: its plugin.json and the font and image files its theme block names. A design system is bundled the same way, as <id>.desk-design. Returned with inline; otherwise written to path, or to <Downloads>/<id>.desk-theme (<id>-2.desk-theme and on when that is taken; .desk-design for a design system), and the file's path returned. */
export interface ThemeExportRequest {
  id: RequestId;
  method: "theme.export";
  params: ThemeExportParams;
}

/** Parameters of theme.export. inline: true takes no path. */
export interface ThemeExportParams {
  theme: PluginId;
  /** Where to write the bundle; an existing file there is replaced. */
  path?: Path;
  /** Return the bundle instead of writing it. */
  inline?: boolean;
  scope: ThemeManagePermission;
}

/** Result of theme.export: the bundle with inline, otherwise the file written. */
export interface ThemeExportResult {
  /** The file written, as an absolute path. */
  path?: string;
  bundle?: ThemeBundle;
}

/** Remove a user theme: its folder goes and plugin.changed says removed. Only themes in the user themes folder (local. and market. ids); any other plugin is invalid_params, an id nothing holds not_found. A removed theme that desk.theme.active names leaves the desk's own theme in force. */
export interface ThemeRemoveRequest {
  id: RequestId;
  method: "theme.remove";
  params: ThemeRemoveParams;
}

/** Parameters of theme.remove. */
export interface ThemeRemoveParams {
  theme: PluginId;
  scope: ThemeManagePermission;
}

/** Result of theme.remove. */
export type ThemeRemoveResult = Record<string, never>;

/** An https URL of a market index (specs/plugin ThemeIndex, desk-theme-index/1). */
export type ThemeMarketUrl = string;

/** Read every market index desk.theme.markets and then desk.design.markets list (ADR 0091), in order, and merge their themes by id: the first market that lists an id wins. Each index is downloaded over https from its own host only; one that cannot be read or is not a valid index leaves its themes out and says why in problems. Each theme says whether this desk has it. */
export interface ThemeMarketListRequest {
  id: RequestId;
  method: "theme.market.list";
  params: ThemeMarketListParams;
}

/** Parameters of theme.market.list. */
export interface ThemeMarketListParams {
  scope: ThemeManagePermission;
}

/** Result of theme.market.list: the merged themes in market order, and the markets that could not be read. */
export interface ThemeMarketListResult {
  themes: ThemeMarketTheme[];
  problems: ThemeMarketProblem[];
}

/** One theme a market offers: its index entry with url made absolute, the market that listed it, and how it stands on this desk. */
export interface ThemeMarketTheme {
  theme: ThemeIndexEntry;
  market: ThemeMarketUrl;
  state: ThemeMarketState;
  /** The version this desk has, when it has the theme. */
  installed?: Version;
}

/** available: not installed. installed: installed as the market publishes it now. update: installed from a market and unchanged since, and the market has other bytes now; installing it again replaces it. edited: installed but not as a market published it (changed since, or brought in from a file); an update never replaces it. */
export type ThemeMarketState = "available" | "installed" | "update" | "edited";

/** A market index that could not be read, and why. */
export interface ThemeMarketProblem {
  market: string;
  message: string;
}

/** Download a market theme to look at it before installing it: over https from the URL's host only, refused unless its bytes match sha256, and checked as a theme plugin in a temporary folder that goes again. Nothing is installed; the answer is the bundle, which the studio previews. */
export interface ThemeMarketFetchRequest {
  id: RequestId;
  method: "theme.market.fetch";
  params: ThemeMarketFetchParams;
}

/** Parameters of theme.market.fetch. */
export interface ThemeMarketFetchParams {
  url: ThemeBundleUrl;
  sha256: ThemeSha256;
  scope: ThemeManagePermission;
}

/** Result of theme.market.fetch: the checked bundle. */
export interface ThemeMarketFetchResult {
  bundle: ThemeBundle;
}

/** A token's name as @endue-ai/ui names it, camelCase: textMuted is the custom property --desk-text-muted, text2xs is --desk-text-2xs. */
export type ThemeTokenName = string;

/** Every token of the look in force, by name, with its CSS value as the shell applies it: colours (#hex, rgb(), rgba(), hsl(), oklch()), lengths in px, box shadows, font stacks, durations, and var(--desk-<token>) references to other tokens (a design system's component tokens are such references). */
export type ThemeTokenMap = Record<string, string>;

/** The runtime, which resolves the look while it still does (ADR 0056, ADR 0090), hands the core the look in force each time it changes (a setting, the OS, a preview, an installed theme or design system): the theme's six layers and the design system's component tokens in one flat table. The core keeps the latest table, whole and in memory only, for the compositor, which draws the desk's chrome from it and follows its var() references (ADR 0146). The same table again changes nothing. */
export interface ThemeTokensRequest {
  id: RequestId;
  method: "theme.tokens";
  params: ThemeTokensParams;
}

/** Parameters of theme.tokens: the look the runtime resolved. */
export interface ThemeTokensParams {
  scheme: ThemeScheme;
  contrast: ThemeContrast;
  /** Whether motion is reduced; the motion tokens are 0ms then. */
  reducedMotion: boolean;
  /** The theme plugin in force or previewed; empty or absent for the desk's own. */
  theme?: string;
  /** The design system in force; empty or absent for the endue design system. */
  design?: string;
  tokens: ThemeTokenMap;
  scope: ThemeManagePermission;
}

/** Result of theme.tokens: the table's revision, which moves only when the table changed, and how many tokens it holds. */
export interface ThemeTokensResult {
  revision: number;
  tokens: number;
}

/** Open one of the surfaces the caller's manifest declares; the runtime hears ui.surface.opened. */
export interface UiSurfaceOpenRequest {
  id: RequestId;
  method: "ui.surface.open";
  params: UiSurfaceOpenParams;
}

/** Parameters of ui.surface.open. */
export interface UiSurfaceOpenParams {
  /** A surface id from the manifest. */
  surface: string;
  placement?: SurfacePlacement;
  title?: string;
  scope: UiSurfacePermission;
}

/** Result of ui.surface.open. */
export interface UiSurfaceOpenResult {
  /** Names the open surface. */
  handle: string;
}

/** Close a surface the caller opened; the runtime hears ui.surface.closed. */
export interface UiSurfaceCloseRequest {
  id: RequestId;
  method: "ui.surface.close";
  params: UiSurfaceCloseParams;
}

/** Parameters of ui.surface.close. */
export interface UiSurfaceCloseParams {
  handle: string;
  scope: UiSurfacePermission;
}

/** Result of ui.surface.close. */
export type UiSurfaceCloseResult = Record<string, never>;

/** The runtime asks a plugin's frame for the state to keep before it unloads a surface that is not visible (ADR 0070). Sent to the frame as a desk request, not to the core: it is not a BridgeRequest. Answering is optional; a frame that does not answer comes back cold. */
export interface UiSurfaceStateRequest {
  id: RequestId;
  method: "ui.surface.state";
  params: UiSurfaceStateParams;
}

/** Parameters of ui.surface.state. */
export interface UiSurfaceStateParams {
  /** The surface id from the plugin's manifest whose frame is about to be unloaded. */
  surface: string;
}

/** A plugin's answer to ui.surface.state. The runtime keeps state in memory for the session, at most 64 KiB as UTF-8 JSON (a bigger one is dropped), and hands it back as restored when the frame loads again. */
export interface UiSurfaceStateResult {
  /** Any JSON value the plugin needs to come back as it was: what is open, the caret, the scroll. Absent: nothing to keep, the surface comes back cold. */
  state?: unknown;
}

/** A PNG of a surface's last frame as the compositor holds it, for Eris, agents and tests. A plugin snapshots only its own surfaces; a caller without a manifest (the desk, an agent, the CLI) any surface. */
export interface UiSurfaceSnapshotRequest {
  id: RequestId;
  method: "ui.surface.snapshot";
  params: UiSurfaceSnapshotParams;
}

/** Parameters of ui.surface.snapshot: the plugin whose surface it is and the surface id from its manifest (main when absent). maxWidth and maxHeight bound the image in pixels, keeping its aspect ratio; it is never enlarged. */
export interface UiSurfaceSnapshotParams {
  plugin: PluginId;
  /** A surface id from the plugin's manifest. */
  surface?: string;
  maxWidth?: number;
  maxHeight?: number;
  scope: UiSurfacePermission;
}

/** Result of ui.surface.snapshot: the PNG as base64 (straight alpha), its size in pixels and the scale from the surface's CSS pixels to them, and whether the surface sleeps (its last frame before it slept). */
export interface UiSurfaceSnapshotResult {
  image: string;
  mediaType: "image/png";
  width: number;
  height: number;
  scale: number;
  asleep: boolean;
}

/** Show a notification. */
export interface UiNotifyRequest {
  id: RequestId;
  method: "ui.notify";
  params: UiNotifyParams;
}

/** Parameters of ui.notify. */
export interface UiNotifyParams {
  title: string;
  body?: string;
  level?: NotifyLevel;
  scope: UiNotifyPermission;
}

/** How a notification is presented; info by default. */
export type NotifyLevel = "info" | "success" | "warning" | "error";

/** Result of ui.notify. */
export interface UiNotifyResult {
  notificationId: string;
}

/** A caller's ui.notify passed its permission check; the runtime shows it as its notify policy says. */
export interface UiNotifiedEvent {
  event: "ui.notified";
  data: UiNotifiedData;
}

/** Payload of ui.notified. */
export interface UiNotifiedData {
  notificationId: string;
  /** The plugin that asked. */
  caller: string;
  title: string;
  body?: string;
  level: NotifyLevel;
}

/** A caller's ui.surface.open passed its checks; the runtime mounts the surface as its display policy says. */
export interface UiSurfaceOpenedEvent {
  event: "ui.surface.opened";
  data: UiSurfaceOpenedData;
}

/** Payload of ui.surface.opened. placement and title are the call's, else the manifest's; title is absent when neither has one. */
export interface UiSurfaceOpenedData {
  /** Names the open surface. */
  handle: string;
  /** The plugin that opened it. */
  caller: string;
  /** The surface id from the caller's manifest. */
  surface: string;
  placement: SurfacePlacement;
  title?: string;
}

/** A surface closed: its caller closed it, or the caller unloaded; the runtime unmounts it. */
export interface UiSurfaceClosedEvent {
  event: "ui.surface.closed";
  data: UiSurfaceClosedData;
}

/** Payload of ui.surface.closed. Placement and title are what ui.surface.opened said. */
export interface UiSurfaceClosedData {
  handle: string;
  /** The plugin that opened it. */
  caller: string;
  surface: string;
}

/** Which channel index the desk follows: stable (tagged releases), beta (canary builds promoted after a clean run) or canary (every build of main). */
export type UpdateChannel = "stable" | "beta" | "canary";

/** What the updater is doing. idle: nothing yet since the start. checking: reading the channel index. up-to-date: no newer build for this desk. available: a newer build was chosen and waits for update.download (desk.update.auto is off). downloading: its bytes are on the way. staged: verified and kept on disk, ready for update.apply. applying: installing it; the desk restarts. failed: the last step failed (reason says why); a staged build stays staged. */
export type UpdateState =
  | "idle"
  | "checking"
  | "up-to-date"
  | "available"
  | "downloading"
  | "staged"
  | "applying"
  | "failed";

/** A semantic version without a leading v: 0.2.0, 0.2.1-pre.48. */
export type UpdateVersion = string;

/** The git commit a build was made from, abbreviated or whole. */
export type UpdateCommit = string;

/** The build that is running. */
export interface UpdateBuild {
  version: UpdateVersion;
  commit?: UpdateCommit;
}

/** The build the desk chose to move to. */
export interface UpdateRelease {
  version: UpdateVersion;
  commit?: UpdateCommit;
  /** When it was published, RFC 3339. */
  date?: string;
  /** Where its release notes are: the GitHub release, or the commit for a pre-release. */
  notes?: string;
}

/** The desk's update status, the answer of every update.* call and the data of update.changed. */
export interface UpdateStatus {
  state: UpdateState;
  current: UpdateBuild;
  channel: UpdateChannel;
  /** When the channel index was last read successfully, RFC 3339. Absent before the first check. */
  checkedAt?: string;
  /** The build chosen: present when available, downloading, staged and applying, and when a step for it failed. */
  release?: UpdateRelease;
  /** Whether release is verified and kept on disk, so update.apply can install it. */
  staged?: boolean;
  /** Bytes of release downloaded so far, while downloading. */
  received?: number;
  /** Bytes release takes, when known. */
  total?: number;
  /** Why the last step failed, for people. Present only when failed. */
  reason?: string;
}

/** Parameters of every update.* call: the update:manage scope. */
export interface UpdateParams {
  scope: UpdateManagePermission;
}

/** Read the update status. */
export interface UpdateStatusRequest {
  id: RequestId;
  method: "update.status";
  params: UpdateParams;
}

/** Result of update.status. */
export type UpdateStatusResult = UpdateStatus;

/** Read the channel index now, also when desk.update.check is off. Answers at once with state checking (or the state of a check already running); the outcome arrives as update.changed. With desk.update.auto on, a newer build starts downloading by itself. */
export interface UpdateCheckRequest {
  id: RequestId;
  method: "update.check";
  params: UpdateParams;
}

/** Result of update.check. */
export type UpdateCheckResult = UpdateStatus;

/** Download the chosen build when the state is available. Answers at once with state downloading; invalid_params when no build is available. Progress and the outcome arrive as update.changed. */
export interface UpdateDownloadRequest {
  id: RequestId;
  method: "update.download";
  params: UpdateParams;
}

/** Result of update.download. */
export type UpdateDownloadResult = UpdateStatus;

/** Install the staged build and restart into it. Its signature and sha256 are checked again first. Answers at once with state applying; invalid_params when nothing is staged. A failure arrives as update.changed with state failed, and the build stays staged. */
export interface UpdateApplyRequest {
  id: RequestId;
  method: "update.apply";
  params: UpdateParams;
}

/** Result of update.apply. */
export type UpdateApplyResult = UpdateStatus;

/** Follow another channel: the person's setting desk.update.channel, which the next check reads. Answers the status on the new channel. An unknown channel is invalid_params. */
export interface UpdateSetChannelRequest {
  id: RequestId;
  method: "update.setChannel";
  params: UpdateSetChannelParams;
}

/** Parameters of update.setChannel. */
export interface UpdateSetChannelParams {
  channel: UpdateChannel;
  scope: UpdateManagePermission;
}

/** Result of update.setChannel: the status on the new channel. */
export type UpdateSetChannelResult = UpdateStatus;

/** The update status changed. Sent to holders of update:manage, and to callers subscribed to update.changed. */
export interface UpdateChangedEvent {
  event: "update.changed";
  data: UpdateStatus;
}

/** Where a view comes from: plugin, an enabled view plugin's inline view or one of its view files, read-only; file, the person's file in ~/.desk/views. */
export type ViewSource = "plugin" | "file";

/** A view in either language: an item view of specs/view/v0 (layouts of components over the desk's items, ADR 0032; deprecated, ADR 0103), a universal view (one presentation of entries from any source, ADR 0087) or a page of universal views. One saved in ~/.desk/views must have its id. */
export type AnyView = View | UniversalView | UniversalPage;

/** A view as view.list returns it: where it comes from and, for a plugin's view, the plugin. An item view has a version; a universal view has its type instead and a page its number of sections, and either's title is its id when it has none. */
export interface ViewSummary {
  id: ViewId;
  version?: Version;
  title: Template;
  description?: string;
  /** A universal view's presentation; absent for an item view and a page. */
  type?: UniversalType;
  /** How many views a page lays out; absent for anything but a page. */
  sections?: number;
  source: ViewSource;
  plugin?: PluginId;
}

/** List the views: the person's and the enabled view plugins', one per id. */
export interface ViewListRequest {
  id: RequestId;
  method: "view.list";
  params: ViewListParams;
}

/** Parameters of view.list. */
export interface ViewListParams {
  scope: ViewManagePermission;
}

/** Result of view.list, by view id. */
export interface ViewListResult {
  views: ViewSummary[];
}

/** Read one view whole, the person's or a plugin's. */
export interface ViewGetRequest {
  id: RequestId;
  method: "view.get";
  params: ViewGetParams;
}

/** Parameters of view.get. */
export interface ViewGetParams {
  id: ViewId;
  scope: ViewManagePermission;
}

/** Result of view.get: the view, where it comes from and, for a plugin's view, the plugin. */
export interface ViewGetResult {
  view: AnyView;
  source: ViewSource;
  plugin?: PluginId;
}

/** Save one of the person's views, new or replacing the one with its id. A plugin's view is not saved: an id an enabled view plugin provides is saved only over the person's file of that id. */
export interface ViewSaveRequest {
  id: RequestId;
  method: "view.save";
  params: ViewSaveParams;
}

/** Parameters of view.save. An item view must pass specs/view/v0 and its names must resolve; a universal view must pass universal.schema.json and have its id. */
export interface ViewSaveParams {
  view: AnyView;
  scope: ViewManagePermission;
}

/** Result of view.save. */
export type ViewSaveResult = Record<string, never>;

/** Remove one of the person's views. A plugin's view is not removed. */
export interface ViewRemoveRequest {
  id: RequestId;
  method: "view.remove";
  params: ViewRemoveParams;
}

/** Parameters of view.remove. */
export interface ViewRemoveParams {
  id: ViewId;
  scope: ViewManagePermission;
}

/** Result of view.remove. */
export type ViewRemoveResult = Record<string, never>;

/** A view was saved or removed. Sent to callers that hold view:manage. */
export interface ViewChangedEvent {
  event: "view.changed";
  data: ViewChangedData;
}

/** Payload of view.changed. */
export interface ViewChangedData {
  id: ViewId;
  change: ViewChange;
}

/** What happened to the view. */
export type ViewChange = "saved" | "removed";

